{
  "technical_and_design_decisions": [
    "Implement the transactional context as a transaction-scoped object for the Java contract API, passing it to contract methods and exposing the existing stub and transaction-related APIs. The object will not be shared across concurrent transactions.",
    "Treat U2 and U3 as duplicate statements of the same protos/utils-to-protoutils package reorganization.",
    "Move utility implementations, generated-code references, internal imports, build metadata, and tests from protos/utils to protoutils. Preserve source compatibility with a minimal compatibility layer only where it does not create significant maintenance risk.",
    "Backport the Kafka health-check behavior from the master branch into the 1.4 LTS-compatible code path, adapting configuration and dependency usage to the LTS versions rather than wholesale merging unrelated changes.",
    "Introduce an explicit read-only chaincode invocation path for channel Readers. The path will enforce read-only simulation semantics and reject ledger writes, while retaining existing Writer authorization requirements for normal invocation.",
    "Add a separately configurable peer external endpoint used by service discovery, distinct from the peer's internally reachable gossip endpoint. The configured endpoint will be advertised in discovery responses without changing normal peer listener binding.",
    "Expose peer and orderer software versions through the existing operations service, using the service's current authentication, TLS, and response conventions.",
    "Update representative Go samples to use idiomatic Go naming, error handling, control flow, package organization, and API usage without changing their externally demonstrated behavior.",
    "Use existing project test frameworks, protobuf generation, build tooling, and CI conventions rather than introducing new infrastructure."
  ],
  "assumptions": [
    "The increment targets an existing Hyperledger Fabric repository with a functioning development environment, build system, protobuf tooling, and test infrastructure.",
    "The specification does not identify exact Fabric release commits, so implementation will be based on the current target branch and the existing 1.4 LTS compatibility constraints.",
    "The work covers implementation, unit tests, integration or end-to-end tests where existing harnesses support them, documentation updates, and regression verification.",
    "No redesign of the consensus, membership, Kafka broker, or operations-service security architecture is required.",
    "Kafka health checks are available as an identifiable implementation in the master branch and can be adapted without resolving unrelated branch divergence.",
    "The read-only invocation feature can be enforced by the peer/chaincode execution path and does not require arbitrary static analysis of chaincode source code.",
    "Service discovery already exists and only requires endpoint configuration and response propagation, not a new discovery protocol.",
    "Version information can be obtained from existing build-time version variables or release metadata for both peers and orderers.",
    "U8 requires updates to representative existing Go samples, not a complete rewrite or creation of a new sample suite.",
    "Estimates represent hands-on work-hours for one developer and exclude elapsed waiting time, external review delays, and major upstream changes discovered after implementation begins."
  ],
  "activities": [
    {
      "activity_id": "A1",
      "activity_name": "Repository analysis and detailed design",
      "activity_description": "Inspect affected peer, orderer, chaincode, Java contract API, protobuf, service-discovery, operations-service, Kafka, sample, build, and test components; map dependencies and define implementation interfaces and compatibility boundaries.",
      "most_likely_effort": 20
    },
    {
      "activity_id": "A2",
      "activity_name": "Transactional context implementation",
      "activity_description": "Implement the Java transaction-scoped context, wire it into contract method invocation, expose the stub and related APIs, handle lifecycle and thread-safety concerns, update API documentation, and add focused unit tests.",
      "most_likely_effort": 36
    },
    {
      "activity_id": "A3",
      "activity_name": "Protos utilities package reorganization",
      "activity_description": "Move protos/utils functionality to protoutils, update package declarations, generated-code references, imports, build manifests, and tests, and provide or validate compatibility handling for affected consumers.",
      "most_likely_effort": 20
    },
    {
      "activity_id": "A4",
      "activity_name": "Kafka health-check backport",
      "activity_description": "Port Kafka health-check logic to the 1.4 LTS-compatible branch, adapt configuration and dependency interfaces, integrate startup and monitoring behavior, and add failure, recovery, and compatibility tests.",
      "most_likely_effort": 44
    },
    {
      "activity_id": "A5",
      "activity_name": "Reader-authorized read-only chaincode invocation",
      "activity_description": "Add the explicit read-only invocation flow, authorize channel Readers for that flow, enforce that the transaction cannot perform ledger writes, preserve existing Writer authorization for normal invocation, and add peer, chaincode, authorization, and negative-path tests.",
      "most_likely_effort": 72
    },
    {
      "activity_id": "A6",
      "activity_name": "Configurable service-discovery external endpoint",
      "activity_description": "Add peer configuration for an explicitly advertised external endpoint, propagate it through gossip or discovery response construction, define precedence and validation behavior, update configuration documentation, and test internal-versus-external endpoint scenarios.",
      "most_likely_effort": 44
    },
    {
      "activity_id": "A7",
      "activity_name": "Operations-service version reporting",
      "activity_description": "Add authenticated operations-service endpoints or response fields for peer and orderer software versions, connect them to build metadata, handle unavailable or malformed version data, and add client and service tests.",
      "most_likely_effort": 36
    },
    {
      "activity_id": "A8",
      "activity_name": "Idiomatic Go sample updates",
      "activity_description": "Review the targeted Go samples, refactor them toward idiomatic Go style and current project APIs, preserve instructional behavior, update sample documentation, and verify that the examples build and execute.",
      "most_likely_effort": 32
    },
    {
      "activity_id": "A9",
      "activity_name": "Cross-component integration and regression testing",
      "activity_description": "Run and extend integration tests covering package relocation, transaction context propagation, Kafka health behavior, Reader read-only invocation, service-discovery endpoint advertisement, operations version queries, and sample compatibility; diagnose and fix regressions.",
      "most_likely_effort": 72
    },
    {
      "activity_id": "A10",
      "activity_name": "Documentation and release-note updates",
      "activity_description": "Document new APIs, configuration settings, authorization behavior, service-discovery endpoint semantics, operations-service version usage, migration implications of the package move, and the user-visible changes in release notes.",
      "most_likely_effort": 20
    },
    {
      "activity_id": "A11",
      "activity_name": "Build, CI, and final verification",
      "activity_description": "Update CI and build definitions for moved packages and new tests, regenerate required artifacts, run the complete relevant test and lint suites, perform final packaging checks, and prepare the increment for review or release.",
      "most_likely_effort": 24
    }
  ],
  "reported_total": {
    "most_likely_effort": 420
  }
}

